window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a02a40c55d3bc2e"]={"versions": [{"id": "FIG-3a02a40c55d3bc2e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit eingebetteten Zustandsmarkern (<em>State Invariants</em>: <code>GOSLEEP</code>, <code>SLEEP</code>, <code>HALT</code>, <code>WAKEUP I</code>) und annotierten Constraints.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Modul <strong>ECU State Manager</strong> (AUTOSAR_SWS_ECUStateManager, Release R20-11, Sleep &amp; Wakeup Management).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten sequenziellen Ablaufs für den Übergang eines Steuergeräts in den Schlafmodus (<em>Sleep Sequence</em> via Halt-Instruktion) sowie der anschließenden asynchronen Aufwecksequenz über einen externen Interrupt der Input Capture Unit (ICU Wakeup by ISR Cat 2) und die Rückkehr in den aktiven Betriebsmodus.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Lifelines</h5>\n<ul class=\"fig-list\"><li><strong><code>«module» EcuM</code></strong>: BSW-Modul ECU State Manager (System Service; Träger des Task-/Thread-Kontexts der Zustandsmaschine).\n</li><li><strong><code>Integration Code</code></strong>: ECU-spezifischer Callout- und Glue-Code (zuständig für die Vermittlung hardwarenaher Konfigurationsschritte und Taktstabilisierung).\n</li><li><strong><code>«module» Os</code></strong>: AUTOSAR Operating System (Verwaltung von Scheduler-Ressourcen und globaler Interrupt-Sperre).\n</li><li><strong><code>«module» Mcu</code></strong>: MCAL-Treiber Microcontroller (Steuerung der Core-Power-Modes und PLL-Zustände).\n</li><li><strong><code>«module» Wakeup Source</code></strong>: Abstrahierter Peripherie-Treiber / Kommunikationsstack (z. B. Can, Lin, Fr oder generic <code>&lt;Module&gt;</code>).\n</li><li><strong><code>«module» Icu</code></strong>: MCAL-Treiber Input Capture Unit (Erfassung externer Flanken/Pegel als Wakeup-Quelle).\n</li><li><strong><code>«Peripheral» ICU Hardware</code></strong>: Physischer Peripherie-Pin / Interrupt-Controller der MCU.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; APIs</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Aufrufer</th><th>Ziel</th><th>API / Signal</th><th>Semantik / Typ</th></tr></thead><tbody><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur selektiven Scharfschaltung der Wakeup-Quellen</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_EnableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Wakeup-Aktivierung am ICU-Kanal</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>GetResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Belegung der Core-spezifischen Scheduler-Ressource</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>DisableAllInterrupts()</code> / <code>EnableAllInterrupts()</code></td><td>Globale Interrupt-Maskierung</td></tr><tr><td><code>EcuM</code></td><td><code>Mcu</code></td><td><code>Mcu_SetMode(Mcu_ModeType)</code></td><td>Anforderung des Low-Power-Modus (Übergang in CPU-Halt)</td></tr><tr><td><code>ICU Hardware</code></td><td><code>Icu</code></td><td><code>Wakeup interrupt()</code></td><td>Asynchroner Hardware-Interrupt (ISR Cat 2)</td></tr><tr><td><code>Icu</code></td><td><code>Integration Code</code></td><td><code>EcuM_CheckWakeup(EcuM_WakeupSourceType)</code></td><td>Rückruf aus ISR-Kontext zur Validierung</td></tr><tr><td><code>Integration Code</code></td><td><code>Wakeup Source</code></td><td><code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code></td><td>Prüfung der Wakeup-Bedingung auf Quellenebene</td></tr><tr><td><code>Wakeup Source</code></td><td><code>EcuM</code></td><td><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code></td><td>Setzen des Wakeup-Events im internen EcuM-Statusregister</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur Deaktivierung der Aufweckkanäle</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_DisableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Deaktivierung des ICU-Wakeups</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Freigabe der Scheduler-Ressource zur Wiederaufnahme normaler Tasks</td></tr></tbody></table></div>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Vorbereitung und Eintritt in den Schlafmodus (<code>GOSLEEP</code> → <code>SLEEP</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Wakeup-Aktivierung:</strong> Im Status <code>GOSLEEP</code> ruft <code>EcuM</code> den Callout <code>EcuM_EnableWakeupSources()</code> auf. Der <code>Integration Code</code> delegiert an <code>Icu_EnableWakeup()</code>.\n</li><li><strong>Scheduler-Blockierung:</strong> <code>EcuM</code> belegt die systemweite Ressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>.\n<ul class=\"fig-list\"><li><em>Zweck:</em> Verhindert ein präemptives Rescheduling nach Abarbeitung nachfolgender ISRs (Kategorie 2), damit der Kontrollfluss nach dem CPU-Wakeup garantiert in der EcuM-Task verbleibt.\n</li></ul>\n</li><li><strong>Interrupt-Maskierung:</strong> <code>EcuM</code> ruft <code>DisableAllInterrupts()</code> auf, um Race Conditions vor dem Mode-Switch auszuschließen.\n</li><li><strong>Halt-Zustand:</strong> <code>EcuM</code> ruft <code>Mcu_SetMode()</code>. Der MCU-Treiber setzt das Register für den Low-Power-Modus und führt den CPU-Stopp-Befehl aus (<code>HALT</code> / WFI / SLEEP). Der CPU-Core verharrt im stromsparenden Wartezustand.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Asynchrones Wakeup &amp; ISR-Abarbeitung (im Status <code>HALT</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>ICU Hardware</code> erkennt das Wecksignal und triggert <code>Wakeup interrupt()</code>. Die Hardware verlässt <code>HALT</code>.\n</li><li><strong>ISR Cat 2 Execution:</strong> Die CPU verzweigt in die ISR des ICU-Treibers.\n</li><li><strong>Takt-Reaktivierung:</strong> <code>Icu</code> ruft <code>EcuM_CheckWakeup()</code> im <code>Integration Code</code> auf. Dieser führt unmittelbar <code>activate PLL()</code> aus, um den Mikrocontroller auf den für Peripheriezugriffe erforderlichen Takt einzuschwingen.\n</li><li><strong>Validierung &amp; Event-Meldung:</strong> \n<ul class=\"fig-list\"><li><code>Integration Code</code> fragt über <code>&lt;Module&gt;_CheckWakeup()</code> das Quellmodul ab.\n</li><li><code>Wakeup Source</code> verifiziert die Anforderung und meldet das valide Event synchron via <code>EcuM_SetWakeupEvent()</code> an den <code>EcuM</code>.\n</li></ul>\n</li><li><strong>ISR-Exit:</strong> Die Call-Kaskade kehrt zurück, und die ICU-ISR endet mit <code>Return from interrupt()</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fortsetzung des EcuM-Kontrollflusses (<code>WAKEUP I</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Un-Halt der Task:</strong> Da <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> aktiv ist, wird kein Task-Wechsel initiiert. Die Programmausführung setzt unmittelbar nach der HALT-Instruktion im blockierten <code>Mcu_SetMode()</code> fort und kehrt zum <code>EcuM</code> zurück.\n</li><li><strong>Interrupt-Wiederherstellung:</strong> <code>EcuM</code> öffnet mit <code>EnableAllInterrupts()</code> kurzzeitig die Interrupt-Sperre.\n</li><li><strong>Modus-Restaurierung (<code>WAKEUP I</code>):</strong>\n<ul class=\"fig-list\"><li>Unter geschütztem Kontext (<code>DisableAllInterrupts()</code>) stellt <code>EcuM</code> via <code>Mcu_SetMode()</code> den regulären MCU-Normalmodus (<em>Run Mode</em>) wieder her und hebt die Sperre via <code>EnableAllInterrupts()</code> wieder auf.\n</li></ul>\n</li><li><strong>Wakeup-Deaktivierung:</strong> <code>EcuM</code> ruft <code>EcuM_DisableWakeupSources()</code>, woraufhin der <code>Integration Code</code> via <code>Icu_DisableWakeup()</code> den ICU-Kanal dekonfiguriert, um Folgeinterrupts im Normalbetrieb zu unterbinden.\n</li><li><strong>Scheduler-Freigabe:</strong> <code>EcuM</code> ruft <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code>. Das reguläre OS-Scheduling ist reaktiviert; nachgelagerte Tasks können ausgeführt werden.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kritische OS-Ressourcen-Bindung (<code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>):</strong> \n<ul class=\"fig-list\"><li>Der Standard erzwingt die Nutzung dieser Standard-OS-Ressource. Wird sie im <code>GOSLEEP</code> nicht akquiriert, führt das Verlassen der Cat-2-ISR (<code>Return from interrupt()</code>) zu einem OS-Rescheduling. Höher- oder gleichpriorisierte Anwendungs-Tasks würden starten, bevor der MCU-Takt, die Peripherie-Betriebsmodi und die Interrupt-Vektoren im <code>WAKEUP I</code> wiederhergestellt sind.\n</li></ul>\n</li><li><strong>Hardware-Interrupt-Design bei globaler Maskierung:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm verlangt <code>DisableAllInterrupts()</code> vor <code>Mcu_SetMode()</code>. Der Mikrocontroller bzw. Interrupt-Controller (NVIC, GIC etc.) muss zwingend hardwareseitig unterstützen, dass maskierte oder privilegierte Wakeup-Interrupts den Core aus dem Schlafzustand wecken (<em>Wakeup Event vs. Interrupt Request</em>).\n</li></ul>\n</li><li><strong>Takt-Reihenfolge im Integration Code (<code>activate PLL()</code>):</strong>\n<ul class=\"fig-list\"><li>Vor dem Aufruf von <code>&lt;Module&gt;_CheckWakeup()</code> muss der Systemtakt stabilisiert werden. MCAL-Treiber (z. B. SPI, CAN, FlexRay) dürfen nicht mit unzulässigem oder instabilem Takt angesprochen werden, da dies Hard-Faults oder Bus-Errors auslöst.\n</li></ul>\n</li><li><strong>Flanken- und Pegelentprellung:</strong>\n<ul class=\"fig-list\"><li>Die Trennung von <code>Icu_EnableWakeup()</code> und der späteren Validierung über <code>EcuM_CheckWakeup()</code> / <code>&lt;Module&gt;_CheckWakeup()</code> stellt sicher, dass Spikes auf dem ICU-Pin nicht unmittelbar zu einem vollen System-Hochlauf führen, falls die Validierung fehlschlägt.\n</li></ul>\n</li><li><strong>Multi-Core-Konformität:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation nutzt den Platzhalter <code>&lt;core#&gt;</code>. Auf Multi-Core-Systemen muss die Schlafsequenz core-spezifisch synchronisiert werden (EcuM Master/Slave-Core-Handling gemäß AUTOSAR Multi-Core-Sleep-Konzept).\n</li></ul>\n</li></ul>"}, {"id": "FIG-2e941c4dbf530a35", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit eingebetteten Zustandsmarkern (<em>State Invariants</em>: <code>GOSLEEP</code>, <code>SLEEP</code>, <code>HALT</code>, <code>WAKEUP I</code>) und annotierten Constraints.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Modul <strong>ECU State Manager</strong> (AUTOSAR_SWS_ECUStateManager, Release R20-11, Sleep &amp; Wakeup Management).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten sequenziellen Ablaufs für den Übergang eines Steuergeräts in den Schlafmodus (<em>Sleep Sequence</em> via Halt-Instruktion) sowie der anschließenden asynchronen Aufwecksequenz über einen externen Interrupt der Input Capture Unit (ICU Wakeup by ISR Cat 2) und die Rückkehr in den aktiven Betriebsmodus.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Lifelines</h5>\n<ul class=\"fig-list\"><li><strong><code>«module» EcuM</code></strong>: BSW-Modul ECU State Manager (System Service; Träger des Task-/Thread-Kontexts der Zustandsmaschine).\n</li><li><strong><code>Integration Code</code></strong>: ECU-spezifischer Callout- und Glue-Code (zuständig für die Vermittlung hardwarenaher Konfigurationsschritte und Taktstabilisierung).\n</li><li><strong><code>«module» Os</code></strong>: AUTOSAR Operating System (Verwaltung von Scheduler-Ressourcen und globaler Interrupt-Sperre).\n</li><li><strong><code>«module» Mcu</code></strong>: MCAL-Treiber Microcontroller (Steuerung der Core-Power-Modes und PLL-Zustände).\n</li><li><strong><code>«module» Wakeup Source</code></strong>: Abstrahierter Peripherie-Treiber / Kommunikationsstack (z. B. Can, Lin, Fr oder generic <code>&lt;Module&gt;</code>).\n</li><li><strong><code>«module» Icu</code></strong>: MCAL-Treiber Input Capture Unit (Erfassung externer Flanken/Pegel als Wakeup-Quelle).\n</li><li><strong><code>«Peripheral» ICU Hardware</code></strong>: Physischer Peripherie-Pin / Interrupt-Controller der MCU.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; APIs</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Aufrufer</th><th>Ziel</th><th>API / Signal</th><th>Semantik / Typ</th></tr></thead><tbody><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur selektiven Scharfschaltung der Wakeup-Quellen</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_EnableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Wakeup-Aktivierung am ICU-Kanal</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>GetResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Belegung der Core-spezifischen Scheduler-Ressource</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>DisableAllInterrupts()</code> / <code>EnableAllInterrupts()</code></td><td>Globale Interrupt-Maskierung</td></tr><tr><td><code>EcuM</code></td><td><code>Mcu</code></td><td><code>Mcu_SetMode(Mcu_ModeType)</code></td><td>Anforderung des Low-Power-Modus (Übergang in CPU-Halt) bzw. Normalmodus</td></tr><tr><td><code>ICU Hardware</code></td><td><code>Icu</code></td><td><code>Wakeup interrupt()</code></td><td>Asynchroner Hardware-Interrupt (ISR Cat 2)</td></tr><tr><td><code>Icu</code></td><td><code>EcuM</code></td><td><code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code></td><td>Aufruf aus ISR-Kontext zur Weckvalidierung (Tippfehler im Diagramm: <em>CheckWakup</em>)</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code></td><td>Callout-Hook zur Plattform-/Hardware-spezifischen Weckbehandlung</td></tr><tr><td><code>Integration Code</code></td><td><code>Wakeup Source</code></td><td><code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code></td><td>Prüfung der Wakeup-Bedingung auf Quellenebene</td></tr><tr><td><code>Wakeup Source</code></td><td><code>EcuM</code></td><td><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code></td><td>Direktes Setzen des Wakeup-Events im internen EcuM-Statusregister</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur Deaktivierung der Aufweckkanäle</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_DisableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Deaktivierung des ICU-Wakeups</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Freigabe der Scheduler-Ressource zur Wiederaufnahme normaler Tasks</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Vorbereitung und Eintritt in den Schlafmodus (<code>GOSLEEP</code> → <code>SLEEP</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Wakeup-Aktivierung:</strong> Im Status <code>GOSLEEP</code> ruft <code>EcuM</code> den Callout <code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code> auf. Der <code>Integration Code</code> delegiert via <code>Icu_EnableWakeup(Icu_ChannelType)</code> an den ICU-Treiber.\n</li><li><strong>Scheduler-Blockierung:</strong> <code>EcuM</code> belegt die systemweite Ressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>.\n<ul class=\"fig-list\"><li><em>Zweck:</em> Verhindert ein präemptives Rescheduling nach Abarbeitung nachfolgender ISRs (Kategorie 2), damit der Kontrollfluss nach dem CPU-Wakeup garantiert in der EcuM-Task verbleibt.\n</li></ul>\n</li><li><strong>Interrupt-Maskierung:</strong> <code>EcuM</code> ruft <code>DisableAllInterrupts()</code> auf, um Race Conditions vor dem Mode-Switch auszuschließen.\n</li><li><strong>Halt-Zustand:</strong> <code>EcuM</code> ruft <code>Mcu_SetMode(Mcu_ModeType)</code>. Der MCU-Treiber setzt das Register für den Low-Power-Modus und führt den CPU-Stopp-Befehl aus (<code>HALT</code> / WFI / SLEEP). Der CPU-Core verharrt im stromsparenden Wartezustand.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Asynchrones Wakeup &amp; ISR-Abarbeitung (im Status <code>HALT</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>ICU Hardware</code> erkennt das Wecksignal und triggert <code>Wakeup interrupt()</code>. Die Hardware verlässt <code>HALT</code>.\n</li><li><strong>ISR Cat 2 Execution:</strong> Die CPU verzweigt in die ISR des ICU-Treibers.\n</li><li><strong>EcuM-Weckprüfung:</strong> <code>Icu</code> ruft <code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code> direkt am <code>EcuM</code> auf.\n</li><li><strong>Callout-Hook &amp; Takt-Reaktivierung:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft den Hook <code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.\n</li><li><code>Integration Code</code> führt unmittelbar <code>activate PLL()</code> aus, um den Mikrocontroller auf den für Peripheriezugriffe erforderlichen Takt einzuschwingen.\n</li></ul>\n</li><li><strong>Validierung &amp; Event-Meldung:</strong>\n<ul class=\"fig-list\"><li><code>Integration Code</code> fragt über <code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code> das Quellmodul ab.\n</li><li><code>Wakeup Source</code> verifiziert die Anforderung und meldet das valide Event direkt via <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an den <code>EcuM</code>.\n</li></ul>\n</li><li><strong>ISR-Exit:</strong> Die Call-Kaskade kehrt zurück, und die ICU-ISR endet mit <code>Return from interrupt()</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fortsetzung des EcuM-Kontrollflusses (<code>WAKEUP I</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Un-Halt der Task:</strong> Da <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> aktiv ist, wird kein Task-Wechsel initiiert. Die Programmausführung setzt unmittelbar nach der HALT-Instruktion im blockierten <code>Mcu_SetMode()</code> fort und kehrt zum <code>EcuM</code> zurück.\n</li><li><strong>Interrupt-Wiederherstellung:</strong> <code>EcuM</code> öffnet mit <code>EnableAllInterrupts()</code> kurzzeitig die Interrupt-Sperre.\n</li><li><strong>Modus-Restaurierung (<code>WAKEUP I</code>):</strong>\n<ul class=\"fig-list\"><li>Unter geschütztem Kontext (<code>DisableAllInterrupts()</code>) stellt <code>EcuM</code> via <code>Mcu_SetMode(Mcu_ModeType)</code> den regulären MCU-Normalmodus (<em>Run Mode</em>) wieder her und hebt die Sperre via <code>EnableAllInterrupts()</code> wieder auf.\n</li></ul>\n</li><li><strong>Wakeup-Deaktivierung:</strong> <code>EcuM</code> ruft <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>, woraufhin der <code>Integration Code</code> via <code>Icu_DisableWakeup(Icu_ChannelType)</code> den ICU-Kanal dekonfiguriert, um Folgeinterrupts im Normalbetrieb zu unterbinden.\n</li><li><strong>Scheduler-Freigabe:</strong> <code>EcuM</code> ruft <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code>. Das reguläre OS-Scheduling ist reaktiviert; nachgelagerte Tasks können ausgeführt werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kritische OS-Ressourcen-Bindung (<code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>):</strong> \n<ul class=\"fig-list\"><li>Der Standard erzwingt die Nutzung dieser Standard-OS-Ressource. Wird sie im <code>GOSLEEP</code> nicht akquiriert, führt das Verlassen der Cat-2-ISR (<code>Return from interrupt()</code>) zu einem OS-Rescheduling. Höher- oder gleichpriorisierte Anwendungs-Tasks würden starten, bevor der MCU-Takt, die Peripherie-Betriebsmodi und die Interrupt-Vektoren im <code>WAKEUP I</code> wiederhergestellt sind.\n</li></ul>\n</li><li><strong>Hardware-Interrupt-Design bei globaler Maskierung:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm verlangt <code>DisableAllInterrupts()</code> vor <code>Mcu_SetMode()</code>. Der Mikrocontroller bzw. Interrupt-Controller (NVIC, GIC etc.) muss zwingend hardwareseitig unterstützen, dass maskierte oder privilegierte Wakeup-Interrupts den Core aus dem Schlafzustand wecken (<em>Wakeup Event vs. Interrupt Request</em>).\n</li></ul>\n</li><li><strong>Takt-Reihenfolge im Integration Code (<code>activate PLL()</code>):</strong>\n<ul class=\"fig-list\"><li>Vor dem Aufruf von <code>&lt;Module&gt;_CheckWakeup()</code> muss der Systemtakt stabilisiert werden. MCAL-Treiber (z. B. SPI, CAN, FlexRay) dürfen nicht mit unzulässigem oder instabilem Takt angesprochen werden, da dies Hard-Faults oder Bus-Errors auslöst.\n</li></ul>\n</li><li><strong>Flanken- und Pegelentprellung:</strong>\n<ul class=\"fig-list\"><li>Die Trennung von <code>Icu_EnableWakeup()</code> und der späteren Validierung über <code>EcuM_CheckWakeup()</code> / <code>&lt;Module&gt;_CheckWakeup()</code> stellt sicher, dass Spikes auf dem ICU-Pin nicht unmittelbar zu einem vollen System-Hochlauf führen, falls die Validierung fehlschlägt.\n</li></ul>\n</li><li><strong>Multi-Core-Konformität:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation nutzt den Platzhalter <code>&lt;core#&gt;</code>. Auf Multi-Core-Systemen muss die Schlafsequenz core-spezifisch synchronisiert werden (EcuM Master/Slave-Core-Handling gemäß AUTOSAR Multi-Core-Sleep-Konzept).\n</li></ul>\n</li></ul>"}, {"id": "FIG-f4027f05b6844c45", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit eingebetteten Zustandsmarkern (<em>State Invariants</em>: <code>GOSLEEP</code>, <code>SLEEP</code>, <code>HALT</code>, <code>WAKEUP I</code>) und annotierten Constraints.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Modul <strong>ECU State Manager</strong> (AUTOSAR_SWS_ECUStateManager, Release R20-11, Sleep &amp; Wakeup Management).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten sequenziellen Ablaufs für den Übergang eines Steuergeräts in den Schlafmodus (<em>Sleep Sequence</em> via Halt-Instruktion) sowie der anschließenden asynchronen Aufwecksequenz über einen externen Interrupt der Input Capture Unit (ICU Wakeup by ISR Cat 2) und die Rückkehr in den aktiven Betriebsmodus.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Lifelines</h5>\n<ul class=\"fig-list\"><li><strong><code>«module» EcuM</code></strong>: BSW-Modul ECU State Manager (System Service; Träger des Task-/Thread-Kontexts der Zustandsmaschine).\n</li><li><strong><code>Integration Code</code></strong>: ECU-spezifischer Callout- und Glue-Code (zuständig für die Vermittlung hardwarenaher Konfigurationsschritte und Taktstabilisierung).\n</li><li><strong><code>«module» Os</code></strong>: AUTOSAR Operating System (Verwaltung von Scheduler-Ressourcen und globaler Interrupt-Sperre).\n</li><li><strong><code>«module» Mcu</code></strong>: MCAL-Treiber Microcontroller (Steuerung der Core-Power-Modes und PLL-Zustände).\n</li><li><strong><code>«module» Wakeup Source</code></strong>: Abstrahierter Peripherie-Treiber / Kommunikationsstack (z. B. Can, Lin, Fr oder generic <code>&lt;Module&gt;</code>).\n</li><li><strong><code>«module» Icu</code></strong>: MCAL-Treiber Input Capture Unit (Erfassung externer Flanken/Pegel als Wakeup-Quelle).\n</li><li><strong><code>«Peripheral» ICU Hardware</code></strong>: Physischer Peripherie-Pin / Interrupt-Controller der MCU.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; APIs</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Aufrufer</th><th>Ziel</th><th>API / Signal</th><th>Semantik / Typ</th></tr></thead><tbody><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur selektiven Scharfschaltung der Wakeup-Quellen</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_EnableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Wakeup-Aktivierung am ICU-Kanal</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>GetResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Belegung der Core-spezifischen Scheduler-Ressource</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>DisableAllInterrupts()</code> / <code>EnableAllInterrupts()</code></td><td>Globale Interrupt-Maskierung</td></tr><tr><td><code>EcuM</code></td><td><code>Mcu</code></td><td><code>Mcu_SetMode(Mcu_ModeType)</code></td><td>Anforderung des Low-Power-Modus (Übergang in CPU-Halt) bzw. Normalmodus</td></tr><tr><td><code>ICU Hardware</code></td><td><code>Icu</code></td><td><code>Wakeup interrupt()</code></td><td>Asynchroner Hardware-Interrupt (ISR Cat 2)</td></tr><tr><td><code>Icu</code></td><td><code>EcuM</code></td><td><code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code></td><td>Aufruf aus ISR-Kontext zur Weckvalidierung (Tippfehler im Diagramm: <em>CheckWakup</em>)</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code></td><td>Callout-Hook zur Plattform-/Hardware-spezifischen Weckbehandlung</td></tr><tr><td><code>Integration Code</code></td><td><code>Wakeup Source</code></td><td><code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code></td><td>Prüfung der Wakeup-Bedingung auf Quellenebene</td></tr><tr><td><code>Wakeup Source</code></td><td><code>EcuM</code></td><td><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code></td><td>Direktes Setzen des Wakeup-Events im internen EcuM-Statusregister</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur Deaktivierung der Aufweckkanäle</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_DisableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Deaktivierung des ICU-Wakeups</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Freigabe der Scheduler-Ressource zur Wiederaufnahme normaler Tasks</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Vorbereitung und Eintritt in den Schlafmodus (<code>GOSLEEP</code> → <code>SLEEP</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Wakeup-Aktivierung:</strong> Im Status <code>GOSLEEP</code> ruft <code>EcuM</code> den Callout <code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code> auf. Der <code>Integration Code</code> delegiert via <code>Icu_EnableWakeup(Icu_ChannelType)</code> an den ICU-Treiber.\n</li><li><strong>Scheduler-Blockierung:</strong> <code>EcuM</code> belegt die systemweite Ressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>.\n<ul class=\"fig-list\"><li><em>Zweck:</em> Verhindert ein präemptives Rescheduling nach Abarbeitung nachfolgender ISRs (Kategorie 2), damit der Kontrollfluss nach dem CPU-Wakeup garantiert in der EcuM-Task verbleibt.\n</li></ul>\n</li><li><strong>Interrupt-Maskierung:</strong> <code>EcuM</code> ruft <code>DisableAllInterrupts()</code> auf, um Race Conditions vor dem Mode-Switch auszuschließen.\n</li><li><strong>Halt-Zustand:</strong> <code>EcuM</code> ruft <code>Mcu_SetMode(Mcu_ModeType)</code>. Der MCU-Treiber setzt das Register für den Low-Power-Modus und führt den CPU-Stopp-Befehl aus (<code>HALT</code> / WFI / SLEEP). Der CPU-Core verharrt im stromsparenden Wartezustand.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Asynchrones Wakeup &amp; ISR-Abarbeitung (im Status <code>HALT</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>ICU Hardware</code> erkennt das Wecksignal und triggert <code>Wakeup interrupt()</code>. Die Hardware verlässt <code>HALT</code>.\n</li><li><strong>ISR Cat 2 Execution:</strong> Die CPU verzweigt in die ISR des ICU-Treibers.\n</li><li><strong>EcuM-Weckprüfung:</strong> <code>Icu</code> ruft <code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code> direkt am <code>EcuM</code> auf.\n</li><li><strong>Callout-Hook &amp; Takt-Reaktivierung:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft den Hook <code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.\n</li><li><code>Integration Code</code> führt unmittelbar <code>activate PLL()</code> aus, um den Mikrocontroller auf den für Peripheriezugriffe erforderlichen Takt einzuschwingen.\n</li></ul>\n</li><li><strong>Validierung &amp; Event-Meldung:</strong>\n<ul class=\"fig-list\"><li><code>Integration Code</code> fragt über <code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code> das Quellmodul ab.\n</li><li><code>Wakeup Source</code> verifiziert die Anforderung und meldet das valide Event direkt via <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an den <code>EcuM</code>.\n</li></ul>\n</li><li><strong>ISR-Exit:</strong> Die Call-Kaskade kehrt zurück, und die ICU-ISR endet mit <code>Return from interrupt()</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fortsetzung des EcuM-Kontrollflusses (<code>WAKEUP I</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Un-Halt der Task:</strong> Da <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> aktiv ist, wird kein Task-Wechsel initiiert. Die Programmausführung setzt unmittelbar nach der HALT-Instruktion im blockierten <code>Mcu_SetMode()</code> fort und kehrt zum <code>EcuM</code> zurück.\n</li><li><strong>Interrupt-Wiederherstellung:</strong> <code>EcuM</code> öffnet mit <code>EnableAllInterrupts()</code> kurzzeitig die Interrupt-Sperre.\n</li><li><strong>Modus-Restaurierung (<code>WAKEUP I</code>):</strong>\n<ul class=\"fig-list\"><li>Unter geschütztem Kontext (<code>DisableAllInterrupts()</code>) stellt <code>EcuM</code> via <code>Mcu_SetMode(Mcu_ModeType)</code> den regulären MCU-Normalmodus (<em>Run Mode</em>) wieder her und hebt die Sperre via <code>EnableAllInterrupts()</code> wieder auf.\n</li></ul>\n</li><li><strong>Wakeup-Deaktivierung:</strong> <code>EcuM</code> ruft <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>, woraufhin der <code>Integration Code</code> via <code>Icu_DisableWakeup(Icu_ChannelType)</code> den ICU-Kanal dekonfiguriert, um Folgeinterrupts im Normalbetrieb zu unterbinden.\n</li><li><strong>Scheduler-Freigabe:</strong> <code>EcuM</code> ruft <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code>. Das reguläre OS-Scheduling ist reaktiviert; nachgelagerte Tasks können ausgeführt werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kritische OS-Ressourcen-Bindung (<code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>):</strong> \n<ul class=\"fig-list\"><li>Der Standard erzwingt die Nutzung dieser Standard-OS-Ressource. Wird sie im <code>GOSLEEP</code> nicht akquiriert, führt das Verlassen der Cat-2-ISR (<code>Return from interrupt()</code>) zu einem OS-Rescheduling. Höher- oder gleichpriorisierte Anwendungs-Tasks würden starten, bevor der MCU-Takt, die Peripherie-Betriebsmodi und die Interrupt-Vektoren im <code>WAKEUP I</code> wiederhergestellt sind.\n</li></ul>\n</li><li><strong>Hardware-Interrupt-Design bei globaler Maskierung:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm verlangt <code>DisableAllInterrupts()</code> vor <code>Mcu_SetMode()</code>. Der Mikrocontroller bzw. Interrupt-Controller (NVIC, GIC etc.) muss zwingend hardwareseitig unterstützen, dass maskierte oder privilegierte Wakeup-Interrupts den Core aus dem Schlafzustand wecken (<em>Wakeup Event vs. Interrupt Request</em>).\n</li></ul>\n</li><li><strong>Takt-Reihenfolge im Integration Code (<code>activate PLL()</code>):</strong>\n<ul class=\"fig-list\"><li>Vor dem Aufruf von <code>&lt;Module&gt;_CheckWakeup()</code> muss der Systemtakt stabilisiert werden. MCAL-Treiber (z. B. SPI, CAN, FlexRay) dürfen nicht mit unzulässigem oder instabilem Takt angesprochen werden, da dies Hard-Faults oder Bus-Errors auslöst.\n</li></ul>\n</li><li><strong>Flanken- und Pegelentprellung:</strong>\n<ul class=\"fig-list\"><li>Die Trennung von <code>Icu_EnableWakeup()</code> und der späteren Validierung über <code>EcuM_CheckWakeup()</code> / <code>&lt;Module&gt;_CheckWakeup()</code> stellt sicher, dass Spikes auf dem ICU-Pin nicht unmittelbar zu einem vollen System-Hochlauf führen, falls die Validierung fehlschlägt.\n</li></ul>\n</li><li><strong>Multi-Core-Konformität:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation nutzt den Platzhalter <code>&lt;core#&gt;</code>. Auf Multi-Core-Systemen muss die Schlafsequenz core-spezifisch synchronisiert werden (EcuM Master/Slave-Core-Handling gemäß AUTOSAR Multi-Core-Sleep-Konzept).\n</li></ul>\n</li></ul>"}, {"id": "FIG-bcb72731099cb484", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit eingebetteten Zustandsmarkern (<em>State Invariants</em>: <code>GOSLEEP</code>, <code>SLEEP</code>, <code>HALT</code>, <code>WAKEUP I</code>) und annotierten Constraints.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform, Modul <strong>ECU State Manager</strong> (AUTOSAR_SWS_ECUStateManager, Release R20-11, Sleep &amp; Wakeup Management).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten sequenziellen Ablaufs für den Übergang eines Steuergeräts in den Schlafmodus (<em>Sleep Sequence</em> via Halt-Instruktion) sowie der anschließenden asynchronen Aufwecksequenz über einen externen Interrupt der Input Capture Unit (ICU Wakeup by ISR Cat 2) und die Rückkehr in den aktiven Betriebsmodus.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Lifelines</h5>\n<ul class=\"fig-list\"><li><strong><code>«module» EcuM</code></strong>: BSW-Modul ECU State Manager (System Service; Träger des Task-/Thread-Kontexts der Zustandsmaschine).\n</li><li><strong><code>Integration Code</code></strong>: ECU-spezifischer Callout- und Glue-Code (zuständig für die Vermittlung hardwarenaher Konfigurationsschritte und Taktstabilisierung).\n</li><li><strong><code>«module» Os</code></strong>: AUTOSAR Operating System (Verwaltung von Scheduler-Ressourcen und globaler Interrupt-Sperre).\n</li><li><strong><code>«module» Mcu</code></strong>: MCAL-Treiber Microcontroller (Steuerung der Core-Power-Modes und PLL-Zustände).\n</li><li><strong><code>«module» Wakeup Source</code></strong>: Abstrahierter Peripherie-Treiber / Kommunikationsstack (z. B. Can, Lin, Fr oder generic <code>&lt;Module&gt;</code>).\n</li><li><strong><code>«module» Icu</code></strong>: MCAL-Treiber Input Capture Unit (Erfassung externer Flanken/Pegel als Wakeup-Quelle).\n</li><li><strong><code>«Peripheral» ICU Hardware</code></strong>: Physischer Peripherie-Pin / Interrupt-Controller der MCU.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; APIs</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Aufrufer</th><th>Ziel</th><th>API / Signal</th><th>Semantik / Typ</th></tr></thead><tbody><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur selektiven Scharfschaltung der Wakeup-Quellen</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_EnableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Wakeup-Aktivierung am ICU-Kanal</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>GetResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Belegung der Core-spezifischen Scheduler-Ressource</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>DisableAllInterrupts()</code> / <code>EnableAllInterrupts()</code></td><td>Globale Interrupt-Maskierung</td></tr><tr><td><code>EcuM</code></td><td><code>Mcu</code></td><td><code>Mcu_SetMode(Mcu_ModeType)</code></td><td>Anforderung des Low-Power-Modus (Übergang in CPU-Halt) bzw. Normalmodus</td></tr><tr><td><code>ICU Hardware</code></td><td><code>Icu</code></td><td><code>Wakeup interrupt()</code></td><td>Asynchroner Hardware-Interrupt (ISR Cat 2)</td></tr><tr><td><code>Icu</code></td><td><code>EcuM</code></td><td><code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code></td><td>Aufruf aus ISR-Kontext zur Weckvalidierung (Tippfehler im Diagramm: <em>CheckWakup</em>)</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code></td><td>Callout-Hook zur Plattform-/Hardware-spezifischen Weckbehandlung</td></tr><tr><td><code>Integration Code</code></td><td><code>Wakeup Source</code></td><td><code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code></td><td>Prüfung der Wakeup-Bedingung auf Quellenebene</td></tr><tr><td><code>Wakeup Source</code></td><td><code>EcuM</code></td><td><code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code></td><td>Direktes Setzen des Wakeup-Events im internen EcuM-Statusregister</td></tr><tr><td><code>EcuM</code></td><td><code>Integration Code</code></td><td><code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code></td><td>Callout zur Deaktivierung der Aufweckkanäle</td></tr><tr><td><code>Integration Code</code></td><td><code>Icu</code></td><td><code>Icu_DisableWakeup(Icu_ChannelType)</code></td><td>MCAL-Treiber-API zur Deaktivierung des ICU-Wakeups</td></tr><tr><td><code>EcuM</code></td><td><code>Os</code></td><td><code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code></td><td>Freigabe der Scheduler-Ressource zur Wiederaufnahme normaler Tasks</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Phase 1: Vorbereitung und Eintritt in den Schlafmodus (<code>GOSLEEP</code> → <code>SLEEP</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Wakeup-Aktivierung:</strong> Im Status <code>GOSLEEP</code> ruft <code>EcuM</code> den Callout <code>EcuM_EnableWakeupSources(EcuM_WakeupSourceType)</code> auf. Der <code>Integration Code</code> delegiert via <code>Icu_EnableWakeup(Icu_ChannelType)</code> an den ICU-Treiber.\n</li><li><strong>Scheduler-Blockierung:</strong> <code>EcuM</code> belegt die systemweite Ressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>.\n<ul class=\"fig-list\"><li><em>Zweck:</em> Verhindert ein präemptives Rescheduling nach Abarbeitung nachfolgender ISRs (Kategorie 2), damit der Kontrollfluss nach dem CPU-Wakeup garantiert in der EcuM-Task verbleibt.\n</li></ul>\n</li><li><strong>Interrupt-Maskierung:</strong> <code>EcuM</code> ruft <code>DisableAllInterrupts()</code> auf, um Race Conditions vor dem Mode-Switch auszuschließen.\n</li><li><strong>Halt-Zustand:</strong> <code>EcuM</code> ruft <code>Mcu_SetMode(Mcu_ModeType)</code>. Der MCU-Treiber setzt das Register für den Low-Power-Modus und führt den CPU-Stopp-Befehl aus (<code>HALT</code> / WFI / SLEEP). Der CPU-Core verharrt im stromsparenden Wartezustand.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 2: Asynchrones Wakeup &amp; ISR-Abarbeitung (im Status <code>HALT</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Hardware-Trigger:</strong> <code>ICU Hardware</code> erkennt das Wecksignal und triggert <code>Wakeup interrupt()</code>. Die Hardware verlässt <code>HALT</code>.\n</li><li><strong>ISR Cat 2 Execution:</strong> Die CPU verzweigt in die ISR des ICU-Treibers.\n</li><li><strong>EcuM-Weckprüfung:</strong> <code>Icu</code> ruft <code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code> direkt am <code>EcuM</code> auf.\n</li><li><strong>Callout-Hook &amp; Takt-Reaktivierung:</strong>\n<ul class=\"fig-list\"><li><code>EcuM</code> ruft den Hook <code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code> im <code>Integration Code</code> auf.\n</li><li><code>Integration Code</code> führt unmittelbar <code>activate PLL()</code> aus, um den Mikrocontroller auf den für Peripheriezugriffe erforderlichen Takt einzuschwingen.\n</li></ul>\n</li><li><strong>Validierung &amp; Event-Meldung:</strong>\n<ul class=\"fig-list\"><li><code>Integration Code</code> fragt über <code>&lt;Module&gt;_CheckWakeup(EcuM_WakeupSourceType)</code> das Quellmodul ab.\n</li><li><code>Wakeup Source</code> verifiziert die Anforderung und meldet das valide Event direkt via <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> an den <code>EcuM</code>.\n</li></ul>\n</li><li><strong>ISR-Exit:</strong> Die Call-Kaskade kehrt zurück, und die ICU-ISR endet mit <code>Return from interrupt()</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Phase 3: Fortsetzung des EcuM-Kontrollflusses (<code>WAKEUP I</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Un-Halt der Task:</strong> Da <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> aktiv ist, wird kein Task-Wechsel initiiert. Die Programmausführung setzt unmittelbar nach der HALT-Instruktion im blockierten <code>Mcu_SetMode()</code> fort und kehrt zum <code>EcuM</code> zurück.\n</li><li><strong>Interrupt-Wiederherstellung:</strong> <code>EcuM</code> öffnet mit <code>EnableAllInterrupts()</code> kurzzeitig die Interrupt-Sperre.\n</li><li><strong>Modus-Restaurierung (<code>WAKEUP I</code>):</strong>\n<ul class=\"fig-list\"><li>Unter geschütztem Kontext (<code>DisableAllInterrupts()</code>) stellt <code>EcuM</code> via <code>Mcu_SetMode(Mcu_ModeType)</code> den regulären MCU-Normalmodus (<em>Run Mode</em>) wieder her und hebt die Sperre via <code>EnableAllInterrupts()</code> wieder auf.\n</li></ul>\n</li><li><strong>Wakeup-Deaktivierung:</strong> <code>EcuM</code> ruft <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>, woraufhin der <code>Integration Code</code> via <code>Icu_DisableWakeup(Icu_ChannelType)</code> den ICU-Kanal dekonfiguriert, um Folgeinterrupts im Normalbetrieb zu unterbinden.\n</li><li><strong>Scheduler-Freigabe:</strong> <code>EcuM</code> ruft <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code>. Das reguläre OS-Scheduling ist reaktiviert; nachgelagerte Tasks können ausgeführt werden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kritische OS-Ressourcen-Bindung (<code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>):</strong> \n<ul class=\"fig-list\"><li>Der Standard erzwingt die Nutzung dieser Standard-OS-Ressource. Wird sie im <code>GOSLEEP</code> nicht akquiriert, führt das Verlassen der Cat-2-ISR (<code>Return from interrupt()</code>) zu einem OS-Rescheduling. Höher- oder gleichpriorisierte Anwendungs-Tasks würden starten, bevor der MCU-Takt, die Peripherie-Betriebsmodi und die Interrupt-Vektoren im <code>WAKEUP I</code> wiederhergestellt sind.\n</li></ul>\n</li><li><strong>Hardware-Interrupt-Design bei globaler Maskierung:</strong>\n<ul class=\"fig-list\"><li>Das Diagramm verlangt <code>DisableAllInterrupts()</code> vor <code>Mcu_SetMode()</code>. Der Mikrocontroller bzw. Interrupt-Controller (NVIC, GIC etc.) muss zwingend hardwareseitig unterstützen, dass maskierte oder privilegierte Wakeup-Interrupts den Core aus dem Schlafzustand wecken (<em>Wakeup Event vs. Interrupt Request</em>).\n</li></ul>\n</li><li><strong>Takt-Reihenfolge im Integration Code (<code>activate PLL()</code>):</strong>\n<ul class=\"fig-list\"><li>Vor dem Aufruf von <code>&lt;Module&gt;_CheckWakeup()</code> muss der Systemtakt stabilisiert werden. MCAL-Treiber (z. B. SPI, CAN, FlexRay) dürfen nicht mit unzulässigem oder instabilem Takt angesprochen werden, da dies Hard-Faults oder Bus-Errors auslöst.\n</li></ul>\n</li><li><strong>Flanken- und Pegelentprellung:</strong>\n<ul class=\"fig-list\"><li>Die Trennung von <code>Icu_EnableWakeup()</code> und der späteren Validierung über <code>EcuM_CheckWakeup()</code> / <code>&lt;Module&gt;_CheckWakeup()</code> stellt sicher, dass Spikes auf dem ICU-Pin nicht unmittelbar zu einem vollen System-Hochlauf führen, falls die Validierung fehlschlägt.\n</li></ul>\n</li><li><strong>Multi-Core-Konformität:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation nutzt den Platzhalter <code>&lt;core#&gt;</code>. Auf Multi-Core-Systemen muss die Schlafsequenz core-spezifisch synchronisiert werden (EcuM Master/Slave-Core-Handling gemäß AUTOSAR Multi-Core-Sleep-Konzept).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-3a02a40c55d3bc2e", "to": "FIG-2e941c4dbf530a35", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Aufrufziel von <code>EcuM_CheckWakeup</code> geändert:</strong> <code>Icu</code> ruft nicht mehr <code>Integration Code</code>, sondern direkt <code>EcuM</code> auf (im Diagramm mit Tippfehler beschriftet als <code>EcuM_CheckWakup(EcuM_WakeupSourceType)</code>).\n</li><li><strong>Neuer Callout-Hook <code>EcuM_CheckWakeupHook</code>:</strong> <code>EcuM</code> ruft nach Empfang des Weckaufrufs <code>EcuM_CheckWakeupHook(EcuM_WakeupSourceType)</code> auf <code>Integration Code</code> auf.\n</li><li><strong>Aufrufziel von <code>EcuM_SetWakeupEvent</code> geändert:</strong> <code>Wakeup Source</code> ruft <code>EcuM_SetWakeupEvent(EcuM_WakeupSourceType)</code> direkt auf <code>EcuM</code> auf statt zuvor auf <code>Integration Code</code> (der Weiterleitungsaufruf von <code>Integration Code</code> an <code>EcuM</code> entfällt).\n</li><li><strong>Entfall explizit beschrifteter Rückkehrpfeile:</strong> Die beschrifteten Rückkehrpfeile für <code>EcuM_EnableWakeupSources()</code>, <code>Icu_EnableWakeup()</code>, <code>GetResource()</code>, <code>EcuM_SetWakeupEvent()</code>, <code>&lt;Module&gt;_CheckWakeup()</code>, <code>EcuM_CheckWakeup()</code>, <code>Icu_DisableWakeup()</code>, <code>EcuM_DisableWakeupSources()</code> und <code>ReleaseResource()</code> wurden entfernt.\n</li></ul>"}, {"from": "FIG-2e941c4dbf530a35", "to": "FIG-f4027f05b6844c45", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Lifeline-Kopfzeilen (<code>Os</code>, <code>Mcu</code>, <code>Icu</code>):</strong> Das Composite-/Decomposition-Symbol (<code>∞</code>) am unteren Rand der Teilnehmer-Boxen von <code>Os</code>, <code>Mcu</code> und <code>Icu</code> wurde entfernt.\n</li></ul>"}, {"from": "FIG-f4027f05b6844c45", "to": "FIG-bcb72731099cb484", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
